import { toList, Empty as $Empty, isEqual } from "./gleam.mjs";

export function go(items) {
  if (items instanceof $Empty) {
    return toList([]);
  } else {
    let first = items.head;
    let rest = items.tail;
    if (isEqual(toList([first]), toList([1, 2, 3]))) {
      return rest;
    } else {
      return toList([]);
    }
  }
}

export function main() {
  return go(toList([1, 2, 3]));
}

